 url=f\"https://api.census.gov/data/{y}/acs/acs1?get=NAME,B28005_014E,B28005_017E&for=state:08\"
 try:
  print(y, urllib.request.urlopen(url, timeout=10).read().decode())
 except Exception as e:
  print(y, type(e).__name__, e)'"

