\\\\\\\\\\\\":\\\\\\\\\\\\\\\"2023 ACS 5-year B28005 65+ broadband share\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"value\\\\\\\\\\\\\\\":82.6},{\\\\\\\\\\\\\\\"label\\\\\\\\\\\\\\\":\\\\\\\\\\\\\\\"2024 ACS 1-year California B28005 65+ broadband share\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"value\\\\\\\\\\\\\\\":91.4},{\\\\\\\\\\\\\\\"label\\\\\\\\\\\\\\\":\\\\\\\\\\\\\\\"latest ACS 5-year households with broadband subscription\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"value\\\\\\\\\\\\\\\":91.0},{\\\\\\\\\\\\\\\"label\\\\\\\\\\\\\\\":\\\\\\\\\\\\\\\"latest ACS 5-year population 65+ with no computer in household\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"value\\\\\\\\\\\\\\\":8.7}],\\\\\\\\\\\\\\\"drivers\\\\\\\\\\\\\\\":[\\\\\\\\\\\\\\\"Aging-cohort replacement raises 65+ internet adoption\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"Broadband subscription definition includes cellular data, satellite, fixed wireless, and other non-dial-up service\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"Gains should slow as the remaining offline 65+ population is more selected\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"ACS sampling and weighting noise can move a one-year national age subgroup by more than one percentage point\\\\\\\\\\\\\\\"],\\\\\\\\\\\\\\\"sourceContext\\\\\\\\\\\\\\\":[\\\\\\\\\\\\\\\"https://data.census.gov/table/ACSDT1Y2025.B28005?q=B28005\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"https://api.census.gov/data/2024/acs/acs1/groups/B28005.html\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"https://data.census.gov/table/ACSDT5Y2023.B28005?g=040XX00US16%240500000_010XX00US&q=ages+with+broadband+access\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"https://data.census.gov/table/ACSDT1Y2024.B28005?g=040XX00US06&q=Telephone%2C+Computer%2C+and+Internet+Access\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"https://www.census.gov/programs-surveys/acs/data/summary-file.2024.html\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\"https://www.census.gov/data/what-is-data-census-gov/upcoming-releases.html\\\\\\\\\\\\\\\"],\\\\\\\\\\\\\\\"runAt\\\\\\\\\\\\\\\":\\\\\\\\\\\\\\\"2026-07-21T01:39:34Z\\\\\\\\\\\\\\\",\\\\\\